'use strict';
const missionData={
2:{title:'The Half-Labeled Tracker',goal:'Find how far DASH-3 traveled from the stage, then identify its location.',intro:'The tracker’s marks are equally spaced. Use the labeled marks and the location board to find the missing numbers.',hints:['Between 0 and 50, how many equal jumps are there?','The value changes by 50 across two equal spaces.','If two spaces cover 50 meters, how far does one space cover?','Split 50 into two equal jumps of 25. Continue: 0, 25, 50, 75, 100.'],path:'Show your jumps, write an equation, or explain how you found the missing numbers.',check:'Starting at 50, do two of your equal jumps land on 100?'},
3:{title:'Why DASH-3 left the stage?',goal:'Determine why DASH-3 left the stage by checking three explanations against the whole record.',intro:"Use DASH-3's diagnostic record to determine the most likely reason why it left the stage.",hints:['Compare each explanation with the record.','Ask: what supports this explanation, and what would have to be true?','A recharge explanation must fit the power level. Remote steering must fit the command count.','78% is not below 20%. There were zero remote commands. DELIVERY mode and the active route support a programmed delivery.'],path:'Which facts support your choice? How do they help you check the other possible reasons?',check:'Does your explanation fit every part of the record?'},
4:{title:'Back Up One Paw',goal:'Find an open route from Blue Arch to Control Booth so the team can recall DASH-3.',intro:'The team has already reached Blue Arch. The striped skybridge is closed by purple foam. Keep the useful part of the plan and change the part that no longer works.',hints:['Find the first step that is now impossible.','Which parts of the beginning and goal still work?','Keep Blue Arch. Look for a different open connection.','From Blue Arch, use Workshop Hall, then Ground Passage, then Control Booth.'],path:'Which part of the original plan can you keep? What must change?',check:'Does every step connect, avoid the closed bridge, and reach Control Booth?'},
5:{title:'Build the Delivery Model',goal:'Rebuild the five-stop delivery route and identify DASH-3’s final destination at F5.',intro:'The numbered labels fell into the wastebasket! The place names and five routing rules remain. Move the places into an order that fits every rule.',hints:['Start with the rule that gives an exact position.','Keep Bubble Lab and Gear Gallery together, in that order.','Snack Lab comes before that pair. Final Station comes after Gear Gallery.','The order is Charging Dock, Snack Lab, Bubble Lab, Gear Gallery, Final Station.'],path:'Explain how you organized the stops. Which rule gave you a place to start?',check:'Read all five rules again. Does your model fit every one?'}
};
const places=['Gear Gallery','Final Station','Charging Dock','Bubble Lab','Snack Lab'];
const edges=[['Prototype Plaza','Blue Arch'],['Blue Arch','Striped Skybridge'],['Striped Skybridge','Control Booth'],['Blue Arch','Workshop Hall'],['Workshop Hall','Ground Passage'],['Ground Passage','Control Booth']];
const moreKey='thinking-detectives.case2.remaining.v1';
let more={};try{more=JSON.parse(localStorage.getItem(moreKey)||'{}')||{};}catch{}
for(let n=2;n<=5;n++){const v=more[n]||{};more[n]={path:'',spoken:false,checked:false,hints:0,verified:false,complete:false,interval:'',distance:'',destination:'',explanation:'',route:['Blue Arch'],order:[...places],...v};const a=more[n];a.path=typeof a.path==='string'?a.path:'';a.hints=Math.max(0,Math.min(4,Number(a.hints)||0));if(!Array.isArray(a.route)||!a.route.length||a.route.some(p=>!edges.flat().includes(p)))a.route=['Blue Arch'];if(!Array.isArray(a.order)||a.order.length!==5||new Set(a.order).size!==5||a.order.some(p=>!places.includes(p)))a.order=[...places];}
function correctMore(n,a){if(n===2)return String(a.interval).trim()==='25'&&String(a.distance).trim()==='75'&&a.destination==='Prototype Plaza';if(n===3)return a.explanation==='delivery';if(n===4)return a.route[0]==='Blue Arch'&&a.route.at(-1)==='Control Booth'&&!a.route.includes('Striped Skybridge')&&a.route.every((p,i)=>!i||edges.some(([x,y])=>x===p&&y===a.route[i-1]||y===p&&x===a.route[i-1]));if(n===5){const o=a.order;return o.indexOf('Charging Dock')===0&&o.indexOf('Gear Gallery')===o.indexOf('Bubble Lab')+1&&o.indexOf('Snack Lab')<o.indexOf('Bubble Lab')&&o.indexOf('Final Station')>o.indexOf('Gear Gallery')&&Math.abs(o.indexOf('Final Station')-o.indexOf('Charging Dock'))!==1&&a.destination===o[4];}return false;}
function evaluateMore(n,a){if(!correctMore(n,a))return {kind:'retry',text:'Good effort—you gave it a try! This answer needs another look. Give it another try :) If you’d like some help, use the hint section below to reveal one hint at a time.'};if((!a.path.trim()&&!a.spoken)||!a.checked)return {kind:'missing',text:'Your answer fits the clues—well done! Show or explain your path and check it, then click Check My Answer again.'};return {kind:'success',text:'You checked your idea against the clues. Your answer fits! Continue the story to compare your path with the detectives’ path.'};}
for(let n=2;n<=5;n++){more[n].verified=more[n].verified===true&&evaluateMore(n,more[n]).kind==='success';more[n].complete=more[n].complete===true&&more[n].verified;}
function saveMore(){try{localStorage.setItem(moreKey,JSON.stringify(more));}catch{storageOK=false;}const el=document.getElementById('saved');if(el)el.textContent=storageOK?'Your work is saved in this browser.':'Your work is available for this visit. Browser saving is unavailable.';}
function unlocked(n){return n===1||missionSolved(n-1);}
function caseProgress(){return `<nav class="progress" aria-label="Case 2 missions">${[1,2,3,4,5].map(n=>n===1||unlocked(n)?`<a href="#mission${n}">Mission ${n}${missionSolved(n)?' ✓':''}</a>`:`<span>Mission ${n} · locked</span>`).join('')}</nav>`;}
function selectField(id,label,options,value){return `<label class="field" for="${id}">${label}</label><select id="${id}" data-answer="${id}"><option value="">Choose a place</option>${options.map(p=>`<option ${value===p?'selected':''}>${esc(p)}</option>`).join('')}</select>`;}
function taskFields(n,a){if(n===2)return `<div class="tracker-board"><figure><svg viewBox="0 0 260 290" role="img" aria-label="Vertical tracker with five equally spaced ticks: bottom 0, second unlabeled, middle 50, fourth unlabeled with DASH-3 signal, top 100 meters."><path d="M90 30V250" stroke="currentColor" stroke-width="4"/>${[30,85,140,195,250].map(y=>`<path d="M75 ${y}H105" stroke="currentColor" stroke-width="3"/>`).join('')}<g fill="currentColor" font-size="20"><text x="20" y="37">100</text><text x="30" y="92">?</text><text x="30" y="147">50</text><text x="30" y="202">?</text><text x="40" y="257">0</text><text x="115" y="92">← DASH-3</text></g></svg><figcaption>Distance from the stage (meters)</figcaption></figure><table><caption>Location board</caption><tbody>${[['North Gate',25],['Gear Gallery',50],['Prototype Plaza',75],['Transit Hall',100]].map(([p,d])=>`<tr><th scope="row">${p}</th><td>${d} m</td></tr>`).join('')}</tbody></table></div><label class="field" for="interval">One interval is how many meters?</label><input id="interval" data-answer="interval" inputmode="numeric" value="${esc(a.interval)}"><label class="field" for="distance">DASH-3’s signal is how many meters from the stage?</label><input id="distance" data-answer="distance" inputmode="numeric" value="${esc(a.distance)}">${selectField('destination','Where has DASH-3 reached?',['North Gate','Gear Gallery','Prototype Plaza','Transit Hall'],a.destination)}`;
if(n===3)return `<table><caption>DASH-3 diagnostic record</caption><tbody>${[['Current power','78%'],['Automatic charging return','Only below 20%'],['Remote commands during trip','0'],['Mode','DELIVERY'],['Route','STOP 2 OF 5 — ACTIVE'],['Witness report','Three precise turns near Charging Dock']].map(([k,v])=>`<tr><th scope="row">${k}</th><td>${v}</td></tr>`).join('')}</tbody></table><h2>Which is the most likely reason?</h2><p>Select the most likely reason based on DASH-3's diagnostic record</p>${[['recharge','DASH-3 needed to recharge.'],['remote','Someone remotely steered DASH-3.'],['delivery','DASH-3 was completing a programmed delivery.']].map(([v,t])=>`<label class="clue"><input type="radio" name="explanation" data-choice="${v}" ${a.explanation===v?'checked':''}><span>${t}</span></label>`).join('')}`;
if(n===4)return routeBuilder(a);
return `<ol><li>Charging Dock is F1.</li><li>Gear Gallery comes immediately after Bubble Lab.</li><li>Snack Lab comes before Bubble Lab.</li><li>Final Station comes after Gear Gallery.</li><li>Final Station is not beside Charging Dock.</li></ol><h2>Your delivery model</h2><p>Use the move buttons to change the order.</p><ol class="stop-list">${a.order.map((p,i)=>`<li><span><strong>F${i+1}</strong> ${p}</span><div><button class="secondary" data-move="${i},-1" aria-label="Move ${p} up" ${i===0?'disabled':''}>↑ Up</button><button class="secondary" data-move="${i},1" aria-label="Move ${p} down" ${i===4?'disabled':''}>↓ Down</button></div></li>`).join('')}</ol>${selectField('destination','Where is the final delivery at F5?',places,a.destination)}`;}
function extraMission(n,result=null){if(!unlocked(n)){location.hash='mission1';return;}const a=more[n],d=missionData[n];app.innerHTML=`<article class="mission"><a class="back" href="#case2">← Case file</a>${caseProgress()}<div class="eyebrow">CASE 02 · MISSION ${n} OF 5</div><h1>${d.title}</h1><div class="goal"><strong>YOUR GOAL</strong><p>${d.goal}</p></div><p>${d.intro}</p>${taskFields(n,a)}<section class="notebook"><h2>Show Your Path</h2><label class="field" for="path">${d.path}</label><textarea id="path">${esc(a.path)}</textarea><div class="check"><label><input id="spoken" type="checkbox" ${a.spoken?'checked':''}><span>I explained or drew my path with a grown-up instead.</span></label></div><div class="check"><strong>Check your path</strong><p>${d.check}</p><label><input id="checked" type="checkbox" ${a.checked?'checked':''}><span>I checked my path. I can revise it if I need to.</span></label></div><div class="actions"><button id="check-answer">Check My Answer</button><button id="continue" class="secondary" ${a.verified?'':'disabled'}>Continue the Story</button></div><p id="message" role="status" aria-live="polite">${esc(result?.text||(a.verified?evaluateMore(n,a).text:'Check your answer to unlock the next part of the story.'))}</p><p class="status">Your explanation stays in your thinking record. It is not automatically graded.</p><p id="saved" class="status"></p></section><section id="hint-section"><h3>Need a foothold?</h3><p>Optional: reveal one hint at a time. Stop when your thinking starts moving again.</p>${d.hints.slice(0,a.hints).map((h,i)=>`<p class="hint"><strong>${i===3?'Strong hint':'Hint '+(i+1)}</strong><br>${h}</p>`).join('')}<button id="hint" class="secondary" ${a.hints===4?'disabled':''}>${a.hints===4?'All hints revealed':a.hints===3?'Reveal the strong hint':'Show the next hint'}</button></section></article>`;
function changed(){a.verified=false;a.complete=false;document.getElementById('continue').disabled=true;document.getElementById('message').textContent='You changed your path. Check your answer again.';saveMore();}
function redraw(){const y=scrollY;extraMission(n);scrollTo(0,y);}
app.querySelectorAll('[data-answer]').forEach(e=>e.oninput=()=>{a[e.dataset.answer]=e.value;changed();});app.querySelectorAll('[data-choice]').forEach(e=>e.onchange=()=>{a.explanation=e.dataset.choice;changed();});document.getElementById('path').oninput=e=>{a.path=e.target.value;changed();};for(const id of ['spoken','checked'])document.getElementById(id).onchange=e=>{a[id]=e.target.checked;changed();};app.querySelectorAll('[data-move]').forEach(e=>e.onclick=()=>{const [i,delta]=e.dataset.move.split(',').map(Number),j=i+delta;if(j<0||j>4)return;[a.order[i],a.order[j]]=[a.order[j],a.order[i]];changed();redraw();const target=app.querySelector(`[data-move="${j},${delta}"]`);if(target&&!target.disabled)target.focus({preventScroll:true});});document.getElementById('check-answer').onclick=()=>{const r=evaluateMore(n,a);a.verified=r.kind==='success';a.complete=false;if(a.verified)awardMission(n);saveMore();document.getElementById('message').textContent=r.text;document.getElementById('continue').disabled=!a.verified;};document.getElementById('hint').onclick=()=>{a.hints=Math.min(4,a.hints+1);saveMore();redraw();document.getElementById('hint-section').scrollIntoView({block:'nearest'});};document.getElementById('continue').onclick=()=>{if(!a.verified||evaluateMore(n,a).kind!=='success')return;a.complete=true;saveMore();location.hash=`after${n}`;};if(n===4)bindRouteBuilder(changed,redraw);saveMore();mountNavigation();}
const storyParts={
2:{title:'Seventy-Five Meters',paragraphs:['“Zero to fifty takes two equal jumps,” said Remy. “So each jump is twenty-five.” He labeled the tracker: 0, 25, 50, 75, 100. DASH-3’s signal sat at 75 meters: Prototype Plaza.','At the plaza, the robot had already gone. A witness remembered three precise turns near Charging Dock. A diagnostic strip curled out of a printer.','Remy raised his magnifying glass, even though the words were enormous. “I know exactly what happened.”','“Did you check the record?” asked Cammy. “Almost exactly,” said Remy.']},
3:{title:'A Plan That Almost Works',paragraphs:["“Zero remote commands,” said Cammy. “So nobody was steering DASH-3 remotely. And its power was at 78%—well above the level that would send it back to recharge.”", "'He is delivering - with three stops left.' Only the Control Booth could read the destination.", "Cammy traced a route: reach Blue Arch, cross the striped skybridge, enter the Control Booth, send DASH-3's recall command.", "'A sensible plan,' said Cammy. 'Elegant,' said Remy. 'Only four opportunities for disaster,' said Cammy. 'Very restful.'", "At Blue Arch, a foam-powered volcano launched purple bubbles over the skybridge. A worker lowered a sign: SKYBRIDGE CLOSED.", "Remy stared. 'Farewell, beautiful plan.' 'Not all of it,' said Cammy."]},
4:{title:'The Part That Still Worked',paragraphs:['They kept the trip to Blue Arch. They changed the middle: Workshop Hall, then Ground Passage, then Control Booth. The destination stayed the same.','At 2:47, the recall screen paused: SAFE DELIVERY HANDOFF REQUIRED. The record read ITEM: FINAL PRIZE. STOP 4 OF 5. DESTINATION: F5. DUE: 2:58.','The parcel and the trophy had matching labels. DASH-3 had scanned the wrong one—and followed its delivery program. Eleven minutes remained.','One invention had sorted the numbered stop labels into a wastebasket. Only the place names remained: Charging Dock, Snack Lab, Bubble Lab, Gear Gallery, and Final Station.','Cammy found five routing rules. “Diagram, table, list, movable cards,” said Remy. “Choose your detective equipment.”']},
5:{title:'The Last Stop',paragraphs:["Remy checked every rule. The route was F-1 Charging Dock, F-2 Snack Lab, F-3 Bubble Lab, F-4 Gear Gallery, F-5 Final Station.", "'Final Station!' said Calamari. A voice called: 'DELIVERY WAITING. SIGNATURE REQUIRED.' The clock read 2:55.", "DASH-3 tried to place the enormous trophy beside a miniature train. Calamari signed at 2:58. DASH-3 released the trophy and played a two-second victory tune."],closing:["The silver parcel contained a tiny golden caboose - the final prize for the Last-Car Challenge. That was why its label said FINAL PRIZE.", "Cammy reviewed the evidence: matching labels, the nearer trophy, and a five-stop delivery route followed exactly as programmed.", "Calamari looked at both labels. 'All right. That was one thing that could go wrong.' Remy crossed out INTERNATIONAL ROBOT TROPHY SYNDICATE. 'Magnificent. Also impossible.'", "They checked that the tracks, tracker, diagnostic record, revised route, duplicate labels, and F-stop model all agreed. At 3:00 the winner received the trophy. Remy wrote CASE CLOSED - then added a very small question mark."]}
};
function extraStory(n){if(!unlocked(n)||!missionSolved(n)){location.hash=`mission${n}`;return;}const d=storyParts[n];app.innerHTML=`<article class="story">${caseProgress()}<div class="eyebrow">MISSION ${n} · THE STORY CONTINUES</div><h1>${d.title}</h1>${n===3?'<img class="story-art" src="assets/case2-page13.png" alt="The detectives study a map below the skybridge covered in purple foam.">':n===5?'<img class="story-art" src="assets/case2-page20.png" alt="The detectives find DASH-3 and the Golden Question Mark trophy beside a miniature railway.">':''}${d.paragraphs.map(p=>`<p>${p}</p>`).join('')}${d.closing?'<h2>Case Closed</h2>'+d.closing.map(p=>`<p>${p}</p>`).join(''):''}${n===2?'<details class="check"><summary>Optional: try your equal-jump thinking on a new tracker</summary><p>Three equally spaced marks read 10, ?, 30. What number belongs in the middle?</p><svg viewBox="0 0 420 80" role="img" aria-label="Three equally spaced ticks labeled 10, unknown, and 30"><path d="M40 25H380 M40 15V35 M210 15V35 M380 15V35" stroke="currentColor" stroke-width="3"/><g fill="currentColor" font-size="20" text-anchor="middle"><text x="40" y="65">10</text><text x="210" y="65">?</text><text x="380" y="65">30</text></g></svg><p></p><label for="transfer">Middle number</label><input id="transfer" inputmode="numeric"><button id="transfer-check">Check</button><p id="transfer-message" role="status"></p><details><summary>Show a hint</summary><p>From 10 to 30 takes two equal jumps. What can you add twice?</p></details></details>':''}<div class="check"><strong>Compare paths</strong><p>How does the detectives’ path compare with yours? There can be different ways to show your thinking.</p></div><div class="actions"><a class="button" href="#${n===5?'reflection':'mission'+(n+1)}">${n===5?'Open my thinking record':'Begin Mission '+(n+1)}</a><a class="button secondary" href="#mission${n}">Revisit my path</a></div></article>`;if(n===2)document.getElementById('transfer-check').onclick=()=>{document.getElementById('transfer-message').textContent=document.getElementById('transfer').value.trim()==='20'?'Yes! Two jumps of 10 connect 10, 20, and 30.':'Good effort—you gave it a try! Give it another try :) You can open the hint below for help.';};}
function reflection(){if(!unlocked(5)||!missionSolved(5)){location.hash='case2';return;}const r=more.reflection||{badges:[],fact:'',check:'',kept:''};more.reflection=r;const badges=['Clue Finder — I noticed information that helped.','Path Builder — I created a way to organize or begin.','Brave Try — I tried without knowing whether it would work.','Check-It — I tested an answer, claim, or plan.','Try Again — I changed a path and kept going.'];app.innerHTML=`<article class="mission"><div class="eyebrow">CASE 02 · CASE CLOSED</div><h1>Your thinking record</h1><p>This case was solved by building a path. Mark any thinking behaviors you used.</p>${badges.map((b,i)=>`<label class="clue"><input data-badge="${i}" type="checkbox" ${r.badges.includes(i)?'checked':''}><span>${b}</span></label>`).join('')}${[['fact','One useful fact I found'],['check','One thing I checked'],['kept','A part I kept when my plan changed']].map(([k,label])=>`<label class="field" for="reflect-${k}">${label}</label><textarea id="reflect-${k}">${esc(r[k])}</textarea>`).join('')}<h2>The paths you recorded</h2>${[1,2,3,4,5].map(n=>{const a=n===1?s:more[n];return `<details><summary>Mission ${n}</summary><p><strong>My answer:</strong> ${esc(n===1?a.answer:n===2?a.distance+' meters — '+a.destination:n===3?{delivery:'Programmed delivery',remote:'Remote steering',recharge:'Recharge'}[a.explanation]:n===4?a.route.join(' → '):a.order.join(' → '))}</p><p class="record-text">${esc(a.path||'I explained or drew my path with a grown-up.')}</p></details>`;}).join('')}<p class="goal">A strong thinker does not always know the answer first. A strong thinker knows how to keep moving.</p><p id="saved" class="status"></p><div class="actions"><button id="print-record">Print my thinking record</button><a class="button secondary" href="#library">Case library</a><a href="assets/Case2_RunawayRobot_001.pdf#page=28" target="_blank" rel="noopener">Grown-up guide in the PDF</a></div></article>`;app.querySelectorAll('[data-badge]').forEach(e=>e.onchange=()=>{const i=Number(e.dataset.badge);r.badges=e.checked?[...r.badges,i]:r.badges.filter(x=>x!==i);saveMore();});for(const k of ['fact','check','kept'])document.getElementById(`reflect-${k}`).oninput=e=>{r[k]=e.target.value;saveMore();};document.getElementById('print-record').onclick=()=>{app.querySelectorAll('details').forEach(d=>d.open=true);window.print();};saveMore();}
